package com.ludo.trailnav.watch;
import android.app.*;import android.content.*;import android.os.*;import com.google.android.gms.tasks.Tasks;import com.google.android.gms.wearable.*;import com.ludo.trailnav.core.*;import java.io.*;
public final class RouteReceiver extends WearableListenerService{@Override public void onDataChanged(DataEventBuffer es){for(DataEvent e:es){if(e.getType()!=DataEvent.TYPE_CHANGED||!TrailLink.ROUTE_PATH.equals(e.getDataItem().getUri().getPath()))continue;try{DataMap m=DataMapItem.fromDataItem(e.getDataItem()).getDataMap();Asset a=m.getAsset(TrailLink.ROUTE_ASSET);if(a==null)continue;DataClient.GetFdForAssetResponse fd=Tasks.await(Wearable.getDataClient(this).getFdForAsset(a));byte[] data;try(InputStream in=fd.getInputStream()){data=RouteStore.readAll(in);}finally{fd.release();}Route r=RouteStore.save(this,data);Asset pa=m.getAsset(TrailLink.PHOTO_ASSET);File photo=new File(getFilesDir(),"route_photo.jpg");if(pa!=null){DataClient.GetFdForAssetResponse pfd=Tasks.await(Wearable.getDataClient(this).getFdForAsset(pa));try(InputStream in=pfd.getInputStream();FileOutputStream out=new FileOutputStream(photo)){byte[] b=new byte[8192];for(int n;(n=in.read(b))>0;)out.write(b,0,n);}finally{pfd.release();}}else if(photo.exists())photo.delete();getSharedPreferences("route",0).edit().putString("areaName",m.getString(TrailLink.AREA_NAME,"")).putString("photoCredit",m.getString(TrailLink.PHOTO_CREDIT,"")).apply();stopService(new Intent(this,HikeService.class));boolean start=m.getBoolean(TrailLink.START_NOW,false);getSharedPreferences("hike",0).edit().clear().putBoolean("start_pending",start).apply();Vibrator v=(Vibrator)getSystemService(VIBRATOR_SERVICE);if(v!=null)v.vibrate(VibrationEffect.createOneShot(180,VibrationEffect.DEFAULT_AMPLITUDE));Intent open=new Intent(this,WatchActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);if(start)open.putExtra("start",true);startActivity(open);notifyRoute(r.name,start);}catch(Exception ignored){}}}
 private void notifyRoute(String n,boolean start){NotificationManager m=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);m.createNotificationChannel(new NotificationChannel("route_ready","Trail transfers",NotificationManager.IMPORTANCE_HIGH));PendingIntent pi=PendingIntent.getActivity(this,37,new Intent(this,WatchActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification no=new Notification.Builder(this,"route_ready").setSmallIcon(android.R.drawable.ic_menu_mylocation).setContentTitle(start?"Starting trail":"Trail ready").setContentText(n).setContentIntent(pi).setAutoCancel(true).build();try{m.notify(101,no);}catch(Exception ignored){}}
}
